CREATE TABLE IF NOT EXISTS memories (id UUID PRIMARY KEY, user_id UUID, kind TEXT, content TEXT NOT NULL, importance REAL DEFAULT .5, embedding vector(384), created_at TIMESTAMPTZ DEFAULT now()); CREATE TABLE IF NOT EXISTS sync_events (id UUID PRIMARY KEY, user_id UUID, client_id TEXT, sequence BIGINT, event_type TEXT, payload JSONB, created_at TIMESTAMPTZ DEFAULT now(), UNIQUE(user_id,client_id,sequence));
